let _duaIdx = 0;
let _duaBanner = null;
function showDuaNotif(){
  const dua = DUAS_NOTIFS[_duaIdx % DUAS_NOTIFS.length];
  _duaIdx++;
  if(_duaBanner) _duaBanner.remove();
  _duaBanner = document.createElement('div');
  _duaBanner.style.cssText='position:fixed;top:70px;left:50%;transform:translateX(-50%) translateY(-8px);background:linear-gradient(135deg,rgba(10,35,22,.98),rgba(3,10,6,.99));border:1px solid rgba(201,168,76,.45);border-radius:18px;padding:1.1rem 1.3rem 1rem;max-width:370px;width:93%;box-shadow:0 10px 40px rgba(0,0,0,.55);z-index:9999;animation:notifSlide .35s cubic-bezier(.22,1,.36,1) forwards;direction:rtl;font-family:Tajawal,sans-serif;';
  const msgFlat = dua.msg.replace(/\n/g,' ');
  const ctaHtml = dua.cta ? `<div style="margin-top:.8rem;text-align:center"><button onclick="this.closest('[data-dua]').remove()" style="background:rgba(201,168,76,.13);border:1.5px solid rgba(201,168,76,.35);color:var(--gold);font-family:'Scheherazade New',serif;font-size:.9rem;padding:.45rem 2rem;border-radius:50px;cursor:pointer;">${dua.cta}</button></div>` : '';
  _duaBanner.setAttribute('data-dua','1');
  _duaBanner.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.55rem;"><div style="font-size:.75rem;color:var(--gold);font-weight:700;letter-spacing:1.5px;">${dua.title}</div><button onclick="this.closest('[data-dua]').remove()" style="background:none;border:none;color:rgba(201,168,76,.4);cursor:pointer;font-size:.85rem;padding:.1rem .3rem;">✕</button></div><div style="font-size:.9rem;color:var(--cr);line-height:1.75;font-family:'Scheherazade New',serif;">${msgFlat}</div>${ctaHtml}`;
  document.body.appendChild(_duaBanner);
  setTimeout(()=>{ if(_duaBanner){ _duaBanner.remove(); _duaBanner=null; } }, 11000);
}

