// 🕌 الأذان التلقائي — يرن عند دخول وقت كل صلاة
// ════════════════════════════════════════════════════════
let _lastAutoAdhanPrayer = '';
let _lastAutoAdhanDate = '';
let _adhanFiredToday = {};

function checkAutoAdhan(){
  if(!atSettings.auto) return;
  if(!prayerTimes || !Object.keys(prayerTimes).length) return;
  const now = new Date();
  const todayKey = now.toDateString();
  if(!_adhanFiredToday[todayKey]) _adhanFiredToday = {[todayKey]: {}};
  const PRAYERS = [
    {key:'fajr',   name:'الفجر 🌙'},
    {key:'dhuhr',  name:'الظهر ☀️'},
    {key:'asr',    name:'العصر 🌤️'},
    {key:'maghrib',name:'المغرب 🌇'},
    {key:'isha',   name:'العشاء 🌃'},
  ];
  PRAYERS.forEach(p=>{
    if(_adhanFiredToday[todayKey][p.key]) return;
    const dec = prayerTimes[p.key];
    if(!dec || isNaN(dec)) return;
    const t = ((dec%24)+24)%24;
    const h = Math.floor(t), m = Math.floor((t-h)*60);
    const pDate = new Date(now.getFullYear(),now.getMonth(),now.getDate(),h,m,0);
    const diff = Math.abs(now - pDate);
    // في حدود 30 ثانية من وقت الصلاة
    if(diff <= 30000){
      _adhanFiredToday[todayKey][p.key] = true;
      // أذان الفجر له إذن خاص
      if(p.key === 'fajr' && !atSettings.fajr) return;
      // اهتزاز
      if(atSettings.vib && navigator.vibrate) navigator.vibrate([500,300,500,300,500]);
      // عرض إشعار الصلاة
      _showPrayerAlert(p.name, pDate);
      // تشغيل الأذان بعد ثانية
      setTimeout(()=>{ _autoPlayAdhan(); }, 1000);
    }
  });
}

function _showPrayerAlert(prayerName, pDate){
  // إشعار browser
  if(Notification && Notification.permission === 'granted'){
    new Notification('🕌 حان وقت ' + prayerName, {
      body: 'الأذان يبدأ الآن — استعد للصلاة',
      icon: 'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><text y=".9em" font-size="90">🕌</text></svg>'
    });
  }
  // بانر داخلي
  const banner = document.createElement('div');
  banner.style.cssText = 'position:fixed;top:70px;left:50%;transform:translateX(-50%);background:linear-gradient(135deg,rgba(10,35,22,.98),rgba(3,10,6,.99));border:2px solid rgba(201,168,76,.6);border-radius:18px;padding:1.2rem 1.5rem;max-width:360px;width:93%;box-shadow:0 10px 40px rgba(0,0,0,.6),0 0 30px rgba(201,168,76,.2);z-index:10000;animation:notifSlide .35s cubic-bezier(.22,1,.36,1) forwards;direction:rtl;font-family:Tajawal,sans-serif;text-align:center;';
  banner.innerHTML = `
    <div style="font-size:2.2rem;margin-bottom:.4rem">🕌</div>
    <div style="font-family:'Scheherazade New',serif;font-size:1.3rem;color:var(--gold);font-weight:700;margin-bottom:.3rem">حان وقت ${prayerName}</div>
    <div style="font-size:.78rem;color:var(--tm);margin-bottom:.9rem">الأذان يبدأ الآن</div>
    <div style="display:flex;gap:.6rem;justify-content:center;flex-wrap:wrap">
      <button onclick="this.closest('div[style]').remove();_autoPlayAdhan()" style="background:linear-gradient(135deg,rgba(201,168,76,.2),rgba(201,168,76,.1));border:1px solid rgba(201,168,76,.4);color:var(--gold);font-family:Tajawal,sans-serif;font-size:.82rem;padding:.45rem 1.1rem;border-radius:50px;cursor:pointer;">🔊 تشغيل الأذان</button>
      <button onclick="this.closest('div[style]').remove()" style="background:none;border:1px solid rgba(201,168,76,.2);color:var(--tm);font-family:Tajawal,sans-serif;font-size:.82rem;padding:.45rem 1.1rem;border-radius:50px;cursor:pointer;">إغلاق</button>
    </div>`;
  document.body.appendChild(banner);
  setTimeout(()=>{ if(banner.parentNode) banner.remove(); }, 30000);
}

function _autoPlayAdhan(){
  if(!atSettings.auto) return;
  var idx = 0;
  try { idx = parseInt(localStorage.getItem('nq_adhan_idx')||'0',10)||0; } catch(e){}
  var keys = ['makkah','madinah','misri','turki'];
  var key = keys[idx] || 'makkah';
  var urls = [];
  try {
    if (typeof ADHAN_URLS !== 'undefined' && ADHAN_URLS[key]) urls = ADHAN_URLS[key].slice();
    else if (typeof ADHAN_SHEIKHS !== 'undefined' && ADHAN_SHEIKHS[idx]) urls = (ADHAN_SHEIKHS[idx].urls||[]).slice();
  } catch(e){}
  if (!urls.length) urls = ['https://www.islamcan.com/audio/adhan/azan1.mp3'];
  if(!adhanAud) adhanAud = new Audio();
  adhanAud.pause();
  function tryN(){ if(!urls.length) return; adhanAud.src=urls.shift(); adhanAud.play().catch(tryN); }
  tryN();
  try {
    var names = {fajr:'الفجر',dhuhr:'الظهر',asr:'العصر',maghrib:'المغرب',isha:'العشاء'};
    if (typeof showAdhanLive === 'function') showAdhanLive('الأذان');
  } catch(e){}
}

// فحص كل 15 ثانية
setInterval(checkAutoAdhan, 15000);


// ════════════════ بحث في آيات السورة ════════════════
function searchInSurah(query){
  const q = query.trim();
  const ayahs = document.querySelectorAll('#qreader .ayah-wrap, #qreader .av');
  const countEl = document.getElementById('ayah-search-count');
  if(!q){
    ayahs.forEach(a=>{ a.style.display=''; a.style.background=''; });
    if(countEl) countEl.style.display='none';
    return;
  }
  let found = 0;
  ayahs.forEach(a=>{
    const txt = a.textContent||'';
    if(txt.includes(q)){
      a.style.display='';
      a.style.background='rgba(201,168,76,.07)';
      a.style.borderRadius='8px';
      found++;
    } else {
      a.style.display='none';
    }
  });
  if(countEl){
    countEl.style.display = 'block';
    countEl.textContent = found > 0 ? `وُجد ${found} آية تحتوي على "${q}"` : `لم تُوجد نتائج لـ "${q}"`;
  }
}
function clearAyahSearch(){
  const inp = document.getElementById('ayah-search-inp');
  if(inp){ inp.value=''; searchInSurah(''); }
}



