// جلب نص الآيات من API
async function fetchAyahsForTafsir(sn){
  try{
    const r = await HudaQuran.fetch(`https://api.alquran.cloud/v1/surah/${sn}`);
    const d = await r.json();
    return (d.data?.ayahs || []).map(a => ({n: a.numberInSurah, text: a.text}));
  }catch{ return []; }
}

