// ════════════════════════════════════════════════
// ❓ نظام الأسئلة الإسلامية — مع مستويات وعشوائية
// ════════════════════════════════════════════════
let _quizQuestions=[], _quizIdx=0, _quizCorrect=0, _quizAnswered=false, _quizCat='الكل', _quizLevel='all';

const QUIZ_LEVELS_MAP={
  easy:['القرآن','الصلاة','العقيدة','الآداب'],
  medium:['السيرة','الأنبياء','الزكاة','الصيام','الحج'],
  hard:['التاريخ','المناسبات','الأذكار','معلومات','المساجد']
};

function setQuizLevel(level){
  _quizLevel=level;
  const labels={easy:'🟢 سهل',medium:'🟡 متوسط',hard:'🔴 صعب',all:'🌟 الكل'};
  const lbl=document.getElementById('qz-level-label');
  if(lbl) lbl.textContent='المستوى: '+labels[level];
}

function shuffleArr(arr){
  const a=[...arr];
  for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}
  return a;
}

function initQuizPage() {
  const wrap = document.getElementById('quiz-cats-wrap');
  if (!wrap || wrap.children.length) return;
  const cats = ['الكل', ...new Set(QUIZ_DATA.map(q=>q.cat))];
  wrap.innerHTML = cats.map(c =>
    `<button class="qcat-btn${c==='الكل'?' on':''}" onclick="startQuiz('${c}',this)">${c}</button>`
  ).join('');
}

function startQuiz(cat, btn) {
  _quizCat = cat;
  document.querySelectorAll('.qcat-btn').forEach(b=>b.classList.remove('on'));
  if (btn&&btn.classList) btn.classList.add('on');
  else document.querySelector('.qcat-btn')?.classList.add('on');
  
  let pool = QUIZ_DATA.filter(q => cat==='الكل' || q.cat===cat);
  if(_quizLevel&&_quizLevel!=='all'){
    const lvlCats=QUIZ_LEVELS_MAP[_quizLevel];
    if(lvlCats&&lvlCats.length){
      const filtered=pool.filter(q=>lvlCats.includes(q.cat));
      if(filtered.length>0) pool=filtered;
    }
  }
  // Shuffle and take 20
  _quizQuestions = shuffleArr(pool).slice(0,20);
  _quizIdx=0; _quizCorrect=0;
  document.getElementById('quiz-start').style.display='none';
  document.getElementById('quiz-result').style.display='none';
  document.getElementById('quiz-card').style.display='block';
  document.getElementById('quiz-score-wrap').style.display='block';
  showQuizQ();
}

function resetAllQuiz(){
  _quizQuestions=[]; _quizIdx=0; _quizCorrect=0; _quizAnswered=false;
  _quizCat='الكل'; _quizLevel='all';
  document.getElementById('quiz-card').style.display='none';
  document.getElementById('quiz-result').style.display='none';
  document.getElementById('quiz-score-wrap').style.display='none';
  document.getElementById('quiz-start').style.display='block';
  const lbl=document.getElementById('qz-level-label');
  if(lbl) lbl.textContent='المستوى: الكل';
}

function showQuizQ() {
  if (_quizIdx >= _quizQuestions.length) { endQuiz(); return; }
  const q = _quizQuestions[_quizIdx];
  _quizAnswered = false;
  document.getElementById('qz-num').textContent = `سؤال ${_quizIdx+1}`;
  document.getElementById('qz-q').textContent = q.q;
  const opts = document.getElementById('qz-opts');
  opts.innerHTML = q.opts.map((o,i) =>
    `<button class="qopt" onclick="answerQuiz(${i})">${o}</button>`
  ).join('');
  document.getElementById('qz-explain').style.display='none';
  document.getElementById('qz-next').style.display='none';
  updateQuizScore();
}

function answerQuiz(i) {
  if (_quizAnswered) return;
  _quizAnswered = true;
  const q = _quizQuestions[_quizIdx];
  const btns = document.querySelectorAll('.qopt');
  btns.forEach((b,j) => {
    b.disabled=true;
    if(j===q.a) b.classList.add('correct');
    else if(j===i) b.classList.add('wrong');
  });
  if (i===q.a) {
    _quizCorrect++;
    if(navigator.vibrate) navigator.vibrate(30);
  } else {
    if(navigator.vibrate) navigator.vibrate([80,40,80]);
  }
  if (q.exp) {
    const ex = document.getElementById('qz-explain');
    ex.textContent = '💡 '+q.exp;
    ex.style.display='block';
  }
  document.getElementById('qz-next').style.display='block';
  updateQuizScore();
}

function quizNext() {
  _quizIdx++;
  showQuizQ();
}

function updateQuizScore() {
  const pct = _quizIdx>0 ? Math.round(_quizCorrect/_quizIdx*100) : 0;
  document.getElementById('qz-correct').textContent = _quizCorrect;
  document.getElementById('qz-total').textContent = _quizIdx;
  document.getElementById('qz-pct').textContent = pct+'٪';
  document.getElementById('quiz-fill').style.width = pct+'%';
}

function endQuiz() {
  document.getElementById('quiz-card').style.display='none';
  const res = document.getElementById('quiz-result');
  res.style.display='block';
  const pct=Math.round(_quizCorrect/_quizQuestions.length*100);
  document.getElementById('qz-final-score').textContent=`${_quizCorrect}/${_quizQuestions.length}`;
  const msg = pct>=90?'🏆 ممتاز! أنت عالم إسلامي':pct>=70?'🌟 رائع جداً، استمر':pct>=50?'👍 جيد، راجع ما فاتك':'📚 تعلّم وحاول مجدداً';
  document.getElementById('qz-final-msg').textContent=msg;
  if(navigator.vibrate) navigator.vibrate([200,100,200,100,400]);
}


// ══ stopAdhan ══
function stopAdhan(){
  if(adhanAud){adhanAud.pause();try{adhanAud.currentTime=0;}catch(e){}}
  _adhanPlaying=false;
  var icon=document.getElementById('adhan2-play-icon');
  var txt=document.getElementById('adhan2-play-txt');
  var now2=document.getElementById('adhan2-now');
  if(icon)icon.textContent='🔊';
  if(txt)txt.textContent='تشغيل الأذان الآن';
  if(now2)now2.style.display='none';
}

// ══ syncAdhan2Cards ══
function syncAdhan2Cards(){
  var idx=typeof _selectedAdhanIdx!=='undefined'?_selectedAdhanIdx:0;
  document.querySelectorAll('#adhan2-grid .adhan-mc').forEach(function(c,i){
    c.classList.toggle('on',i===idx);
  });
}

// ══ adhan2SetVol ══
function adhan2SetVol(val){
  var v=parseInt(val)/100;
  if(adhanAud)adhanAud.volume=v;
  try{localStorage.setItem('nq_adhan_vol',val);}catch(e){}
}


// ══ Translation System ══
var _showTranslation = localStorage.getItem('nq_trans')==='1';
var _translationCache = {};

function toggleTranslation(){
  _showTranslation = !_showTranslation;
  localStorage.setItem('nq_trans', _showTranslation?'1':'0');
  var btn = document.getElementById('trans-btn');
  if(btn) btn.classList.toggle('on', _showTranslation);
  if(currentSurahN) loadSurah(currentSurahN);
}

async function getTranslation(surahN){
  if(_translationCache[surahN]) return _translationCache[surahN];
  try{
    const r = await HudaQuran.fetch(`https://api.alquran.cloud/v1/surah/${surahN}/en.sahih`);
    const d = await r.json();
    if(d.data && d.data.ayahs){
      _translationCache[surahN] = d.data.ayahs.map(a=>a.text);
      return _translationCache[surahN];
    }
  }catch(e){}
  return null;
}




