var ASMA_COLORS=['#1a3a2a','#0d2a1a','#1a2a0d','#0d1a2a','#2a1a0d','#1a0d2a'];

function buildAsma(){
  var grid=document.getElementById('asma-grid');
  if(!grid) return;
  if(grid.children.length>0) return; // already built
  ASMA_DATA.forEach(function(a,i){
    var card=document.createElement('div');
    card.style.cssText='background:'+ASMA_COLORS[i%6]+';border:1px solid rgba(201,168,76,.22);border-radius:14px;padding:1rem .8rem;cursor:pointer;transition:background .25s;text-align:center;';
    card.innerHTML='<div style="font-family:\'Scheherazade New\',serif;font-size:1.25rem;color:#f0d080;margin-bottom:.35rem;">'+(i+1)+'. '+a.n+'</div>'
      +'<div style="font-size:.76rem;color:rgba(255,255,255,.6);line-height:1.5;">'+a.m+'</div>';
    card.onclick=function(){
      document.querySelectorAll('#asma-grid>div[data-sel]').forEach(function(c){c.removeAttribute('data-sel');c.style.background=ASMA_COLORS[parseInt(c.dataset.i)%6];});
      card.setAttribute('data-sel','1');
      card.style.background='rgba(201,168,76,.2)';
    };
    card.dataset.i=i;
    grid.appendChild(card);
  });
}

