// 🔍 بحث في القرآن الكريم
// ═══════════════════════════════════════════════
var _qsTimer=null;
function doQSearch(){
  clearTimeout(_qsTimer);
  _qsTimer=setTimeout(function(){
    var q=(document.getElementById('qsearch-inp')?document.getElementById('qsearch-inp').value:'').trim();
    var res=document.getElementById('qsearch-results');
    var stats=document.getElementById('qsearch-stats');
    if(!res||!stats) return;
    if(q.length<2){ res.innerHTML=''; stats.textContent=''; return; }
    var smArr=typeof SM!=='undefined'?SM:[];
    // البحث في السور
    var found=smArr.filter(function(s){ return s.ar&&s.ar.includes(q); });
    // البحث في التفسير المحلي
    var ayahResults=[];
    if(typeof TDATA_LOCAL!=='undefined'){
      Object.keys(TDATA_LOCAL).forEach(function(sn){
        var arr=TDATA_LOCAL[sn];
        for(var i=0;i<arr.length;i++){
          var item=arr[i];
          if((item.ay&&item.ay.includes(q))||(item.tx&&item.tx.includes(q))){
            var s=smArr[parseInt(sn)-1];
            ayahResults.push({sn:parseInt(sn),surahAr:s?s.ar:'سورة '+sn,ay:item.ay,tx:item.tx});
          }
        }
      });
    }
    var total=found.length+ayahResults.length;
    stats.textContent='وُجد '+total+' نتيجة للبحث عن: "'+q+'"';
    var html='';
    if(found.length){
      html+='<div style="color:var(--gold);font-size:.85rem;margin-bottom:.5rem;font-weight:700;">📖 سور ('+found.length+')</div>';
      found.forEach(function(s){
        html+='<div onclick="SP(\'quran\');setTimeout(function(){loadSurah('+s.n+');},400);" style="background:rgba(201,168,76,.08);border:1px solid rgba(201,168,76,.18);border-radius:12px;padding:.8rem 1rem;margin-bottom:.5rem;cursor:pointer;display:flex;justify-content:space-between;align-items:center;">'
          +'<div><span style="color:#f0d080;font-family:\'Scheherazade New\',serif;font-size:1.1rem;">سورة '+s.ar+'</span>'
          +' <span style="color:var(--tm);font-size:.75rem;">('+s.ay+' آية — '+s.tp+')</span></div>'
          +'<span style="color:var(--tm);font-size:.75rem;">'+s.n+'</span></div>';
      });
    }
    if(ayahResults.length){
      html+='<div style="color:var(--gold);font-size:.85rem;margin:1rem 0 .5rem;font-weight:700;">✨ نتائج التفسير ('+ayahResults.length+')</div>';
      ayahResults.slice(0,15).forEach(function(r){
        var re=new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','g');
        var hilite=function(t){ return t?t.replace(re,'<mark style="background:rgba(201,168,76,.3);color:#f0d080;border-radius:3px;padding:0 2px;">$1</mark>'):t; };
        html+='<div style="background:rgba(13,59,46,.4);border:1px solid rgba(201,168,76,.15);border-radius:12px;padding:.9rem 1rem;margin-bottom:.6rem;">'
          +'<div style="font-size:.7rem;color:var(--gold);margin-bottom:.4rem;">سورة '+r.surahAr+' ('+r.sn+')</div>'
          +'<div style="font-family:\'Scheherazade New\',serif;font-size:1rem;color:#f0d080;margin-bottom:.4rem;line-height:2;">'+hilite(r.ay)+'</div>'
          +'<div style="font-size:.8rem;color:var(--tm);line-height:1.7;">'+hilite(r.tx)+'</div>'
          +'</div>';
      });
    }
    if(!total) html='<div style="text-align:center;color:var(--tm);padding:2rem;font-size:.9rem;">لم يُعثر على نتائج 🔍<br><span style="font-size:.78rem;">جرّب كلمة أخرى</span></div>';
    res.innerHTML=html;
  },350);
}

