// ☑️ متابعة الصلوات اليومية
// ═══════════════════════════════════════════════
var PRAYERS_LIST=[
  {id:'fajr',  name:'الفجر',   icon:'🌙', time:'قبل الشروق'},
  {id:'dhuhr', name:'الظهر',   icon:'☀️', time:'منتصف النهار'},
  {id:'asr',   name:'العصر',   icon:'🌤', time:'بعد الظهر'},
  {id:'maghrib',name:'المغرب', icon:'🌅', time:'عند الغروب'},
  {id:'isha',  name:'العشاء',  icon:'🌟', time:'بعد المغرب'}
];

function getTrackerKey(){
  var d=new Date();
  return 'trk_'+d.getFullYear()+'_'+(d.getMonth()+1)+'_'+d.getDate();
}

function loadTracker(){
  var key=getTrackerKey();
  var data={};
  try{ var s=localStorage.getItem(key); if(s) data=JSON.parse(s); }catch(e){}
  var container=document.getElementById('tracker-prayers');
  var dateEl=document.getElementById('tracker-date');
  if(!container) return;
  var d=new Date();
  var days=['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
  var months=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
  if(dateEl) dateEl.textContent=days[d.getDay()]+' '+d.getDate()+' '+months[d.getMonth()]+' '+d.getFullYear()+'م';
  container.innerHTML='';
  PRAYERS_LIST.forEach(function(p){
    var done=!!data[p.id];
    var card=document.createElement('div');
    card.style.cssText='background:'+(done?'rgba(201,168,76,.15)':'rgba(201,168,76,.04)')+';border:1px solid rgba(201,168,76,'+(done?'.4':'.12')+');border-radius:16px;padding:1rem 1.2rem;display:flex;align-items:center;justify-content:space-between;cursor:pointer;transition:all .2s;';
    card.innerHTML='<div style="display:flex;align-items:center;gap:.8rem;">'
      +'<span style="font-size:1.5rem;">'+p.icon+'</span>'
      +'<div><div style="font-family:\'Scheherazade New\',serif;font-size:1.1rem;color:'+(done?'#f0d080':'var(--cr)')+';">'+p.name+'</div>'
      +'<div style="font-size:.72rem;color:var(--tm);">'+p.time+'</div></div></div>'
      +'<div style="width:28px;height:28px;border-radius:50%;border:2px solid '+(done?'#C9A84C':'rgba(201,168,76,.3)')+';background:'+(done?'#C9A84C':'transparent')+';display:flex;align-items:center;justify-content:center;color:#0a1f0e;font-weight:700;font-size:.9rem;">'+(done?'✓':'')+'</div>';
    card.onclick=function(){
      data[p.id]=!done;
      try{ localStorage.setItem(key,JSON.stringify(data)); }catch(e){}
      loadTracker();
    };
    container.appendChild(card);
  });
  var doneCount=0; for(var _k in data){if(data.hasOwnProperty(_k)&&data[_k]) doneCount++;}
  var streak=document.getElementById('tracker-streak');
  if(streak){
    var pct=Math.round((doneCount/5)*100);
    streak.innerHTML='<div style="font-size:2rem;margin-bottom:.3rem">'+(doneCount===5?'🎉':'🤲')+'</div>'
      +'<div style="color:var(--gold);font-size:1rem;margin-bottom:.5rem">'+doneCount+' من 5 صلوات اليوم</div>'
      +'<div style="background:rgba(0,0,0,.3);border-radius:10px;height:8px;overflow:hidden;">'
      +'<div style="background:#C9A84C;height:100%;width:'+pct+'%;border-radius:10px;transition:width .5s;"></div></div>'
      +(doneCount===5?'<div style="color:#7ae87a;font-size:.85rem;margin-top:.5rem">ما شاء الله! أتممت صلوات اليوم 🌟</div>':'');
  }
}

function trackerReset(){
  try{ localStorage.removeItem(getTrackerKey()); }catch(e){}
  loadTracker();
}

