// ══════════════════════════════════════════════════════
// 📸 مشاركة آية كصورة
// ══════════════════════════════════════════════════════
function shareAyahAsImage(){
  var ayahEl=document.querySelector('.vbv-text');
  var surahEl=document.querySelector('.vbv-badge');
  var ayahNum=document.querySelector('.vbv-surah-info');
  if(!ayahEl){alert('افتح سورة أولاً ثم اضغط مشاركة');return;}
  var ayahText=ayahEl.innerText||ayahEl.textContent||'';
  var surahName=surahEl?surahEl.innerText:'';
  var numText=ayahNum?ayahNum.innerText:'';
  var c=document.createElement('canvas');
  c.width=900;c.height=500;
  var ctx=c.getContext('2d');
  // خلفية
  var grad=ctx.createLinearGradient(0,0,0,500);
  grad.addColorStop(0,'#030A06');grad.addColorStop(1,'#0D3B2E');
  ctx.fillStyle=grad;ctx.fillRect(0,0,900,500);
  // إطار ذهبي
  ctx.strokeStyle='rgba(201,168,76,0.5)';ctx.lineWidth=2;
  ctx.strokeRect(20,20,860,460);
  ctx.strokeStyle='rgba(201,168,76,0.2)';ctx.lineWidth=1;
  ctx.strokeRect(26,26,848,448);
  // نقاط زخرفية
  var pts=[[20,20],[880,20],[20,480],[880,480]];
  pts.forEach(function(p){
    ctx.fillStyle='#C9A84C';
    ctx.beginPath();ctx.arc(p[0],p[1],5,0,Math.PI*2);ctx.fill();
  });
  // نص السورة
  ctx.fillStyle='rgba(201,168,76,0.7)';
  ctx.font='bold 22px Arial';ctx.textAlign='center';
  ctx.fillText(surahName+' — '+numText,450,70);
  // بسم الله
  ctx.fillStyle='rgba(201,168,76,0.4)';
  ctx.font='20px Arial';
  ctx.fillText('﷽',450,110);
  // الآية - نضطر نستخدم fallback لعدم دعم الخط العربي في canvas
  ctx.fillStyle='#f0d080';
  ctx.font='bold 36px Arial';
  ctx.textAlign='center';
  // تقسيم النص على أسطر
  var words=ayahText.split(' ');
  var lines2=[],line='';
  words.forEach(function(w){
    var test=(line?line+' ':'')+w;
    if(ctx.measureText(test).width>780&&line){lines2.push(line);line=w;}
    else line=test;
  });
  if(line)lines2.push(line);
  var startY=200-(lines2.length-1)*30;
  lines2.forEach(function(l,i){ctx.fillText(l,450,startY+i*60);});
  // اسم الموقع
  ctx.fillStyle='rgba(201,168,76,0.5)';ctx.font='18px Arial';
  ctx.fillText('🌙 هُدى القرآن',450,460);
  // تحميل أو مشاركة
  c.toBlob(function(blob){
    if(navigator.share&&navigator.canShare&&navigator.canShare({files:[new File([blob],'ayah.png',{type:'image/png'})]})){
      navigator.share({files:[new File([blob],'ayah.png',{type:'image/png'})],title:'آية من هُدى القرآن',text:ayahText});
    } else {
      var a=document.createElement('a');a.href=URL.createObjectURL(blob);
      a.download='ayah_noor_quran.png';a.click();
    }
  },'image/png');
}



