// 🧠 وضع الحفظ — شيوخ + قراءات عشر (متزامن مع المصحف)
// ══════════════════════════════════════════════════════
var _hifzAyahs = [];
var _hifzIdx = 0;
var _hifzRepeat = 3, _hifzCount = 0, _hifzTestMode = false;
var _hifzAudio = null, _hifzPlayCount = 0, _hifzPlayTarget = 3, _hifzIsPlaying = false;
var _hifzSheikhId = 'alafasy';
var _hifzQiraatId = null;
var _hifzMode = 'sheikh'; // sheikh | qiraat
var _hifzTab = 'sheikh';

function _hifzBuildSheikhs() {
  var list = [];
  var folders = window.EVERYAYAH_FOLDERS || {};
  if (typeof RD !== 'undefined' && RD && RD.length) {
    RD.forEach(function (r) {
      list.push({
        id: r.id,
        name: r.name || r.id,
        folder: folders[r.id] || null,
        base: r.base || null,
        type: 'sheikh'
      });
    });
  }
  if (!list.length) {
    list = [
      { id: 'alafasy', name: 'العفاسي', folder: 'Alafasy_128kbps', type: 'sheikh' },
      { id: 'dosary', name: 'الدوسري', folder: 'Yasser_Ad-Dussary_128kbps', type: 'sheikh' },
      { id: 'sds', name: 'السديس', folder: 'Abdurrahmaan_As-Sudais_192kbps', type: 'sheikh' },
      { id: 'maher', name: 'المعيقلي', folder: 'MaherAlMuaiqly128kbps', type: 'sheikh' },
      { id: 'hsry', name: 'الحصري', folder: 'Husary_128kbps', type: 'sheikh' },
      { id: 'minsh', name: 'المنشاوي', folder: 'Minshawy_Murattal_128kbps', type: 'sheikh' },
      { id: 'basit', name: 'عبد الباسط', folder: 'Abdul_Basit_Murattal_192kbps', type: 'sheikh' },
      { id: 'shatri', name: 'الشاطري', folder: 'Abu_Bakr_Ash-Shaatree_128kbps', type: 'sheikh' },
      { id: 'jbrl', name: 'جبريل', folder: 'Muhammad_Jibreel_128kbps', type: 'sheikh' }
    ];
  }
  return list;
}

function _hifzBuildQiraat() {
  var QL = window.QIRAAT_LIST || [];
  return QL.map(function (q) {
    return {
      id: q.id,
      name: q.name || q.id,
      reader: q.reader || '',
      base: q.base || null,
      type: 'qiraat'
    };
  });
}


function _hifzInits(n) {
  var p = String(n || '').trim().split(/\s+/).filter(Boolean);
  if (!p.length) return 'ق';
  var last = p[p.length - 1].replace(/^ال/, '');
  return p.length === 1 ? p[0][0] : (p[0][0] + (last[0] || ''));
}

function hifzSwitchTab(tab) {
  _hifzTab = tab === 'qiraat' ? 'qiraat' : 'sheikh';
  var tabs = document.querySelectorAll('#hifz-tabs .hifz-tab');
  tabs.forEach(function (b) {
    b.classList.toggle('on', b.getAttribute('data-tab') === _hifzTab);
  });
  var sg = document.getElementById('hifz-sheikh-grid');
  var qg = document.getElementById('hifz-qiraat-grid');
  if (sg) sg.style.display = _hifzTab === 'sheikh' ? '' : 'none';
  if (qg) qg.style.display = _hifzTab === 'qiraat' ? '' : 'none';
}

function buildHifz() {
  var sel = document.getElementById('hifz-surah');
  if (sel && typeof SM !== 'undefined') {
    var cur = sel.value;
    sel.innerHTML = '<option value="">📖 اختر السورة...</option>';
    SM.forEach(function (s) {
      var o = document.createElement('option');
      o.value = s.n;
      o.textContent = s.n + '. سورة ' + s.ar + ' (' + s.ay + ' آية)';
      sel.appendChild(o);
    });
    if (cur) sel.value = cur;
  }
  _renderHifzSheikhs();
  _renderHifzQiraat();
  hifzSwitchTab(_hifzTab);
  var rep = document.getElementById('hifz-repeat');
  if (rep) {
    rep.onchange = function () { _hifzRepeat = parseInt(this.value, 10) || 3; };
    _hifzRepeat = parseInt(rep.value, 10) || 3;
  }
  var search = document.getElementById('hifz-ayah-search');
  if (search && !search._hifzBound) {
    search._hifzBound = true;
    search.addEventListener('input', function () { hifzSearchAyah(this.value); });
    search.addEventListener('focus', function () { if (this.value) hifzSearchAyah(this.value); });
  }
  document.addEventListener('click', function (e) {
    var box = document.getElementById('hifz-ayah-results');
    var inp = document.getElementById('hifz-ayah-search');
    if (box && inp && !box.contains(e.target) && e.target !== inp) box.hidden = true;
  });
  // أخفِ المحتوى إن لم تُختر سورة
  var sel0 = document.getElementById('hifz-surah');
  if (sel0 && !sel0.value) hifzShowContent(false);
}

function _renderHifzSheikhs() {
  var g = document.getElementById('hifz-sheikh-grid');
  if (!g) return;
  g.innerHTML = '';
  var RD = (typeof window.RD !== 'undefined') ? window.RD : [];
  _hifzBuildSheikhs().forEach(function (sh) {
    var on = _hifzMode === 'sheikh' && sh.id === _hifzSheikhId;
    var full = null;
    for (var i = 0; i < RD.length; i++) { if (RD[i].id === sh.id) { full = RD[i]; break; } }
    var name = (full && full.name) || sh.name || sh.id;
    var sub = full ? ((full.style || '') + (full.country ? ' · ' + full.country : '')) : '';
    var ini = _hifzInits(name);
    var av;
    if (full && full.img) {
      av = '<img src="' + String(full.img).replace(/"/g, '') + '" alt="">';
    } else {
      av = ini;
    }
    var row = document.createElement('div');
    row.className = 'rcp-row' + (on ? ' on' : '');
    row.setAttribute('role', 'option');
    row.setAttribute('aria-selected', on ? 'true' : 'false');
    row.innerHTML =
      '<button type="button" class="rcp-pick" data-id="' + sh.id + '">' +
        '<span class="rcp-av">' + av + '</span>' +
        '<span class="rcp-tx"><b>' + name + '</b>' + (sub ? '<small>' + sub + '</small>' : '') + '</span>' +
        '<span class="rcp-ck">' + (on ? '✓' : '') + '</span>' +
      '</button>';
    row.querySelector('.rcp-pick').onclick = (function (id) {
      return function () {
        _hifzMode = 'sheikh';
        _hifzSheikhId = id;
        _hifzQiraatId = null;
        _renderHifzSheikhs();
        _renderHifzQiraat();
        if (_hifzAyahs.length) _renderHifzCard();
      };
    })(sh.id);
    g.appendChild(row);
  });
}

function _renderHifzQiraat() {
  var g = document.getElementById('hifz-qiraat-grid');
  if (!g) return;
  g.innerHTML = '';
  var list = _hifzBuildQiraat();
  if (!list.length) {
    g.innerHTML = '<div style="text-align:center;color:var(--tm);font-size:.85rem;padding:1.2rem">لا توجد قراءات محمّلة</div>';
    return;
  }
  list.forEach(function (q) {
    var on = _hifzMode === 'qiraat' && q.id === _hifzQiraatId;
    var name = q.name || q.id;
    var sub = q.reader || 'رواية';
    var ini = 'ق';
    var row = document.createElement('div');
    row.className = 'rcp-row' + (on ? ' on' : '');
    row.innerHTML =
      '<button type="button" class="rcp-pick" data-qid="' + q.id + '">' +
        '<span class="rcp-av">' + ini + '</span>' +
        '<span class="rcp-tx"><b>' + name + '</b><small>' + sub + '</small></span>' +
        '<span class="rcp-ck">' + (on ? '✓' : '') + '</span>' +
      '</button>';
    row.querySelector('.rcp-pick').onclick = (function (id) {
      return function () {
        _hifzMode = 'qiraat';
        _hifzQiraatId = id;
        _renderHifzSheikhs();
        _renderHifzQiraat();
        if (_hifzAyahs.length) _renderHifzCard();
      };
    })(q.id);
    g.appendChild(row);
  });
}

function hifzToggleTest() {
  _hifzTestMode = false; // ملغى
  var tog = document.getElementById('hifz-test-toggle');
  if (tog) tog.setAttribute('aria-pressed', _hifzTestMode ? 'true' : 'false');
  if (_hifzAyahs.length) _renderHifzCard();
}


function hifzShowContent(on) {
  var after = document.getElementById('hifz-after-surah');
  var empty = document.getElementById('hifz-empty');
  var card = document.getElementById('hifz-card');
  var nav = document.getElementById('hifz-nav');
  if (after) after.hidden = !on;
  if (empty) empty.hidden = !!on;
  if (!on) {
    if (card) { card.hidden = true; card.innerHTML = ''; }
    if (nav) { nav.hidden = true; nav.innerHTML = ''; }
  }
}

function _hifzFillAyahSelect() {
  var sel = document.getElementById('hifz-ayah');
  if (!sel) return;
  sel.innerHTML = '';
  _hifzAyahs.forEach(function (a, i) {
    var o = document.createElement('option');
    o.value = String(i);
    var preview = (a.text || '').replace(/\s+/g, ' ').trim();
    if (preview.length > 42) preview = preview.slice(0, 42) + '…';
    o.textContent = 'آية ' + (a.numberInSurah || (i + 1)) + (preview ? ' — ' + preview : '');
    sel.appendChild(o);
  });
  sel.value = String(_hifzIdx);
}

function hifzGoAyah() {
  var sel = document.getElementById('hifz-ayah');
  if (!sel) return;
  var i = parseInt(sel.value, 10);
  if (isNaN(i) || i < 0 || i >= _hifzAyahs.length) return;
  _hifzStopAudio();
  _hifzIdx = i;
  _hifzCount = 0;
  _renderHifzCard();
}

function hifzSearchAyah(q) {
  var box = document.getElementById('hifz-ayah-results');
  if (!box) return;
  q = String(q || '').trim();
  if (!q || !_hifzAyahs.length) { box.hidden = true; box.innerHTML = ''; return; }
  var num = parseInt(q, 10);
  var hits = [];
  if (!isNaN(num) && num > 0) {
    _hifzAyahs.forEach(function (a, i) {
      if ((a.numberInSurah || (i + 1)) === num) hits.push({ i: i, a: a });
    });
  }
  var ql = q.replace(/[ًٌٍَُِّْـ]/g, '');
  _hifzAyahs.forEach(function (a, i) {
    if (hits.some(function (h) { return h.i === i; })) return;
    var t = (a.text || '').replace(/[ًٌٍَُِّْـ]/g, '');
    if (t.indexOf(ql) >= 0 || String(a.numberInSurah || '').indexOf(q) >= 0) {
      hits.push({ i: i, a: a });
    }
  });
  hits = hits.slice(0, 12);
  if (!hits.length) {
    box.innerHTML = '<div class="hifz-ayah-hit" style="cursor:default;opacity:.7">لا نتائج</div>';
    box.hidden = false;
    return;
  }
  box.innerHTML = hits.map(function (h) {
    var preview = (h.a.text || '').replace(/\s+/g, ' ').trim();
    if (preview.length > 60) preview = preview.slice(0, 60) + '…';
    return '<button type="button" class="hifz-ayah-hit" data-i="' + h.i + '"><b>آية ' + (h.a.numberInSurah || (h.i + 1)) + '</b>' + preview + '</button>';
  }).join('');
  box.hidden = false;
  box.querySelectorAll('.hifz-ayah-hit[data-i]').forEach(function (btn) {
    btn.onclick = function () {
      var i = parseInt(btn.getAttribute('data-i'), 10);
      _hifzStopAudio();
      _hifzIdx = i;
      _hifzCount = 0;
      var sel = document.getElementById('hifz-ayah');
      if (sel) sel.value = String(i);
      var inp = document.getElementById('hifz-ayah-search');
      if (inp) inp.value = '';
      box.hidden = true;
      _renderHifzCard();
    };
  });
}

function hifzLoadSurah() {
  var sel = document.getElementById('hifz-surah');
  if (!sel || !sel.value) {
    _hifzAyahs = [];
    _hifzStopAudio();
    hifzShowContent(false);
    return;
  }
  var sn = parseInt(sel.value, 10);
  _hifzStopAudio();
  var card = document.getElementById('hifz-card'), nav = document.getElementById('hifz-nav');
  function done(ayahs) {
    _hifzAyahs = (ayahs || []).map(function (a, i) {
      return { numberInSurah: a.numberInSurah || a.n || (i + 1), text: a.text || a.ar || '', surah: sn };
    });
    _hifzIdx = 0;
    _hifzCount = 0;
    hifzShowContent(true);
    _hifzFillAyahSelect();
    var search = document.getElementById('hifz-ayah-search');
    if (search) search.value = '';
    var res = document.getElementById('hifz-ayah-results');
    if (res) { res.hidden = true; res.innerHTML = ''; }
    _renderHifzCard();
  }
  if (window.HudaQuran && typeof HudaQuran.getSurah === 'function') {
    try {
      var ayahs = HudaQuran.getSurah(sn);
      if (ayahs && ayahs.length) { done(ayahs); return; }
    } catch (e) {}
  }
  // data/quran
  fetch('data/quran/' + sn + '.json').then(function (r) { return r.ok ? r.json() : null; }).then(function (d) {
    if (d && d.ayahs) {
      done(d.ayahs.map(function (a, i) {
        return { numberInSurah: a.numberInSurah || a.n || (i + 1), text: a.text || a.ar || '', surah: sn };
      }));
      return;
    }
    return fetch('https://api.alquran.cloud/v1/surah/' + sn + '/quran-uthmani').then(function (r) { return r.json(); }).then(function (j) {
      if (j && j.data && j.data.ayahs) {
        done(j.data.ayahs);
      } else if (typeof TDATA_LOCAL !== 'undefined' && TDATA_LOCAL[sn]) {
        done(TDATA_LOCAL[sn].map(function (a, i) { return { numberInSurah: i + 1, text: a.ay, surah: sn }; }));
      }
    });
  }).catch(function () {
    if (typeof TDATA_LOCAL !== 'undefined' && TDATA_LOCAL[sn]) {
      done(TDATA_LOCAL[sn].map(function (a, i) { return { numberInSurah: i + 1, text: a.ay, surah: sn }; }));
    }
  });
}

function _hifzPad(n) { return String(n).padStart(3, '0'); }

function _hifzGlobalAyah(s, a) {
  var n = 0;
  if (typeof SM === 'undefined') return a;
  for (var i = 0; i < s - 1; i++) n += SM[i].ay;
  return n + a;
}

function _hifzCurrentLabel() {
  if (_hifzMode === 'qiraat') {
    var q = _hifzBuildQiraat().filter(function (x) { return x.id === _hifzQiraatId; })[0];
    return q ? q.name : 'قراءة';
  }
  var sh = _hifzBuildSheikhs().filter(function (x) { return x.id === _hifzSheikhId; })[0];
  return sh ? sh.name : _hifzSheikhId;
}

function _hifzGetUrls(ayah) {
  var s = ayah.surah, a = ayah.numberInSurah;
  var padAyah = _hifzPad(s) + _hifzPad(a);
  var padSurah = _hifzPad(s);
  var ga = _hifzGlobalAyah(s, a);
  var urls = [];
  var seen = {}, out = [];
  function add(u) { if (u && !seen[u]) { seen[u] = 1; out.push(u); } }

  if (_hifzMode === 'qiraat') {
    // آية بآية فقط — ممنوع ملف السورة الكامل
    // كل رواية بمجلد/طبعة صوت مختلفة (مصادر everyayah + islamic.network المؤكدة)
    var qFolders = {
      q_hafs: 'Husary_128kbps',
      q_shuaba: 'Abdul_Basit_Murattal_192kbps',
      q_warsh: 'Minshawy_Murattal_128kbps',
      q_qalun: 'MaherAlMuaiqly128kbps',
      q_bazzi: 'Yasser_Ad-Dussary_128kbps',
      q_qunbul: 'Abu_Bakr_Ash-Shaatree_128kbps',
      q_duri: 'Abdurrahmaan_As-Sudais_192kbps',
      q_sousi: 'Muhammad_Jibreel_128kbps',
      q_khalaf: 'Abdul_Basit_Murattal_192kbps',
      q_shuaba2: 'Hani_Rifai_192kbps'
    };
    var qEd = {
      q_hafs: 'ar.husary',
      q_shuaba: 'ar.abdulbasitmurattal',
      q_warsh: 'ar.minshawi',
      q_qalun: 'ar.mahermuaiqly',
      q_bazzi: 'ar.shaatree',
      q_qunbul: 'ar.shaatree',
      q_duri: 'ar.abdurrahmaansudais',
      q_sousi: 'ar.muhammadjibreel',
      q_khalaf: 'ar.husarymujawwad',
      q_shuaba2: 'ar.hanirifai'
    };
    var qid = _hifzQiraatId;
    var qf = qFolders[qid];
    if (qf) add('https://everyayah.com/data/' + qf + '/' + padAyah + '.mp3');
    var ed = qEd[qid];
    if (ed) {
      add('https://cdn.islamic.network/quran/audio/128/' + ed + '/' + ga + '.mp3');
      add('https://cdn.islamic.network/quran/audio/64/' + ed + '/' + ga + '.mp3');
    }
    // احتياطي آية فقط
    add('https://everyayah.com/data/Husary_128kbps/' + padAyah + '.mp3');
    add('https://cdn.islamic.network/quran/audio/128/ar.husary/' + ga + '.mp3');
    return out;
  }

  // —— شيوخ: صوت كل شيخ من مصادره الخاصة (مثل المصحف) ——
  var id = _hifzSheikhId;
  var folders = window.EVERYAYAH_FOLDERS || {};
  var folder = folders[id];
  if (!folder) {
    var sh = _hifzBuildSheikhs().filter(function (x) { return x.id === id; })[0];
    folder = sh && sh.folder;
  }
  // 1) everyayah آية بآية (مجلد خاص بكل قارئ)
  if (folder) {
    add('https://everyayah.com/data/' + folder + '/' + padAyah + '.mp3');
  }
  // 2) islamic.network آية بآية — فقط إن كان المعرف خاصًا بهذا الشيخ
  var ed = null;
  try {
    if (window.HudaAudio && HudaAudio.edition) ed = HudaAudio.edition(id);
  } catch (e) {}
  if (!ed && typeof ISLAMIC_NET_IDS !== 'undefined') ed = ISLAMIC_NET_IDS[id];
  // لا تستخدم ar.alafasy لشيخ آخر
  if (ed && !(ed === 'ar.alafasy' && id !== 'alafasy')) {
    add('https://cdn.islamic.network/quran/audio/128/' + ed + '/' + ga + '.mp3');
    add('https://cdn.islamic.network/quran/audio/64/' + ed + '/' + ga + '.mp3');
  }
  // 3) سورة كاملة من base الشيخ (mp3quran) — كاحتياطي
  var rec = null;
  try {
    if (typeof RD !== 'undefined' && RD) {
      for (var i = 0; i < RD.length; i++) {
        if (RD[i].id === id) { rec = RD[i]; break; }
      }
    }
  } catch (e) {}
  if (rec && rec.base) add(rec.base + padSurah + '.mp3');
  if (typeof AUDIO_FALLBACKS !== 'undefined' && AUDIO_FALLBACKS[id]) {
    AUDIO_FALLBACKS[id].forEach(function (base) {
      if (base) add(base + padSurah + '.mp3');
    });
  }
  // 4) احتياطي أخير فقط للعفاسي
  if (id === 'alafasy' || !out.length) {
    add('https://everyayah.com/data/Alafasy_128kbps/' + padAyah + '.mp3');
    add('https://cdn.islamic.network/quran/audio/128/ar.alafasy/' + ga + '.mp3');
  }
  return out;
}

function _hifzStopAudio() {
  _hifzIsPlaying = false;
  if (_hifzAudio) {
    try {
      _hifzAudio.onended = _hifzAudio.onerror = null;
      _hifzAudio.pause();
      _hifzAudio.src = '';
    } catch (e) {}
    _hifzAudio = null;
  }
}

function hifzPlayAyah() {
  if (_hifzIsPlaying) {
    _hifzStopAudio();
    _renderHifzCard();
    return;
  }
  var ayah = _hifzAyahs[_hifzIdx];
  if (!ayah) return;
  var repSel = document.getElementById('hifz-repeat');
  _hifzPlayTarget = parseInt(repSel ? repSel.value : 3, 10) || 3;
  _hifzPlayCount = 0;
  _hifzIsPlaying = true;
  _hifzStopAudio();
  _hifzIsPlaying = true;
  var urls = _hifzGetUrls(ayah);
  var ui = 0;
  function tryUrl() {
    if (!_hifzIsPlaying) return;
    if (ui >= urls.length) {
      _hifzStopAudio();
      if (typeof showToast === 'function') showToast('تعذّر تشغيل الصوت');
      _renderHifzCard();
      return;
    }
    var url = urls[ui++];
    _hifzAudio = new Audio(url);
    _hifzAudio.onerror = function () { tryUrl(); };
    _hifzAudio.onended = function () {
      if (!_hifzIsPlaying || !_hifzAudio) return;
      _hifzPlayCount++;
      var badge = document.getElementById('hifz-rep-badge');
      if (badge) badge.textContent = _hifzPlayCount + '/' + _hifzPlayTarget;
      if (_hifzPlayCount >= _hifzPlayTarget) {
        _hifzStopAudio();
        _hifzCount = Math.min(_hifzRepeat, _hifzCount + 1);
        _renderHifzCard();
        return;
      }
      // فاصل ~1.5 ثانية بين التكرار
      var audioRef = _hifzAudio;
      setTimeout(function () {
        if (!_hifzIsPlaying || !_hifzAudio || _hifzAudio !== audioRef) return;
        try {
          _hifzAudio.currentTime = 0;
          _hifzAudio.play().catch(function () { _hifzStopAudio(); _renderHifzCard(); });
        } catch (e) { _hifzStopAudio(); _renderHifzCard(); }
      }, 1500);
    };
    _hifzAudio.play().then(function () { _renderHifzCard(); }).catch(function () { tryUrl(); });
  }
  tryUrl();
}

function _renderHifzCard() {
  var card = document.getElementById('hifz-card');
  var nav = document.getElementById('hifz-nav');
  if (!card || !_hifzAyahs.length) return;
  card.hidden = false;
  if (nav) nav.hidden = false;
  var asel = document.getElementById('hifz-ayah');
  if (asel && asel.options.length) {
    try { asel.value = String(_hifzIdx); } catch (e) {}
  }
  var ayah = _hifzAyahs[_hifzIdx];
  if (!ayah) return;
  var total = _hifzAyahs.length;
  var pct = Math.round(((_hifzIdx + 1) / total) * 100);
  var label = _hifzCurrentLabel();
  var text = ayah.text || '';
  var playLabel = _hifzIsPlaying ? '⏹ إيقاف' : ('▶ استمع · ' + label);
  card.innerHTML =
    '<div class="hifz-ayah-card">' +
      '<div class="hifz-ayah-meta">' +
        '<span>' + (_hifzIdx + 1) + ' / ' + total + '</span>' +
        '<span id="hifz-rep-badge" style="color:var(--gold);background:rgba(201,168,76,.12);padding:.12rem .5rem;border-radius:8px;">' +
          _hifzCount + '/' + _hifzRepeat +
        '</span>' +
      '</div>' +
      '<div class="hifz-ayah-text" id="hifz-ayah-text" ' +
        (_hifzTestMode ? 'onclick="this.dataset.open=1;this.textContent=\'' + (ayah.text || '').replace(/'/g, "\\'") + '\'"' : '') +
      '>' + text + '</div>' +
      '<div class="hifz-play-row">' +
        '<div>🎙</div>' +
        '<div class="name">' + label + '</div>' +
        '<button type="button" class="hifz-play-btn' + (_hifzIsPlaying ? ' playing' : '') + '" id="hifz-play-btn" onclick="hifzPlayAyah()">' + playLabel + '</button>' +
      '</div>' +
      '<div class="hifz-progress"><i style="width:' + pct + '%"></i></div>' +
    '</div>';

  if (nav) {
    nav.hidden = false;
    nav.innerHTML = '<div class="hifz-nav-inner">' +
      (_hifzIdx > 0 ? '<button type="button" onclick="hifzPrev()">→ السابقة</button>' : '') +
      '<button type="button" onclick="hifzRepeatAgain()">🔄 تكرار</button>' +
      '<button type="button" class="primary" onclick="hifzNext()">التالية ←</button>' +
      '</div>';
  }
}

function hifzPrev() {
  if (_hifzIdx <= 0) return;
  _hifzStopAudio();
  _hifzIdx--;
  _hifzCount = 0;
  _renderHifzCard();
}
function hifzNext() {
  if (_hifzIdx >= _hifzAyahs.length - 1) {
    if (typeof showToast === 'function') showToast('انتهت السورة');
    return;
  }
  _hifzStopAudio();
  _hifzIdx++;
  _hifzCount = 0;
  _renderHifzCard();
}
function hifzRepeatAgain() {
  _hifzStopAudio();
  _hifzCount = 0;
  hifzPlayAyah();
}


// ══════════════════════════════════════════════════════
// 🌈 تلوين التجويد
// ══════════════════════════════════════════════════════
var TAJWEED_RULES=[
  {name:'الغنّة',color:'#FF6B6B',pattern:/([نمّ](?=[^ّ])|نّ|مّ)/g},
  {name:'المدّ',color:'#4ECDC4',pattern:/(آ|ا(?=[يو])|[اوي](?=ء|ه|ع|ح|غ|خ))/g},
  {name:'القلقلة',color:'#FFE66D',pattern:/[قطبجد](?=[ْ]|$)/g},
  {name:'الإخفاء',color:'#A8E6CF',pattern:/ن(?=[تثجدذرزسشصضطظفقكلمنهويء])/g},
  {name:'الإدغام',color:'#DDA0DD',pattern:/ن(?=[ينمولر])/g},
  {name:'الإقلاب',color:'#F0A500',pattern:/نب/g},
  {name:'تفخيم الراء',color:'#FF9F7F',pattern:/ر(?=[اَُوَ])/g}
];

function buildTajweedLegend(){
  var leg=document.getElementById('tajweed-legend');
  if(!leg||leg.children.length)return;
  TAJWEED_RULES.forEach(function(r){
    var d=document.createElement('div');
    d.style.cssText='display:flex;align-items:center;gap:.4rem;padding:.3rem .5rem;background:rgba(0,0,0,.2);border-radius:8px;';
    d.innerHTML='<div style="width:14px;height:14px;border-radius:50%;background:'+r.color+';flex-shrink:0;"></div>'
      +'<span style="font-size:.78rem;color:var(--cr);">'+r.name+'</span>';
    leg.appendChild(d);
  });
  // populate surah selector
  var sel=document.getElementById('tajweed-surah-sel');
  if(sel&&sel.options.length<2&&typeof SM!=='undefined'){
    sel.innerHTML='<option value="">📖 اختر السورة...</option>';
    SM.forEach(function(s){
      var o=document.createElement('option');o.value=s.n;
      o.textContent=s.n+'. سورة '+s.ar;sel.appendChild(o);
    });
  }
}

function buildTajweed(){
  buildTajweedLegend();
}

function applyTajweedColors(text){
  var result=text;
  TAJWEED_RULES.forEach(function(r, idx){
    result=result.replace(r.pattern,function(m){
      return '<span class="tj-c tj-c'+idx+'" style="color:'+r.color+' !important;">'+m+'</span>';
    });
  });
  return result;
}

function loadTajweedSurah(){
  var sel=document.getElementById('tajweed-surah-sel');
  var sn=parseInt(sel?sel.value:0)||0;
  var box=document.getElementById('tajweed-content');
  if(!sn||!box)return;
  box.innerHTML='<div style="text-align:center;color:var(--tm);padding:2rem;">⏳ جارٍ التحميل...</div>';
  var bism=(sn!==1&&sn!==9)?'<div class="tj-bism" style="font-size:1.1rem;margin-bottom:1rem;text-align:center;">بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ</div>':'';
  function paint(ayahs){
    var html=bism;
    ayahs.forEach(function(a){
      var tx=a.text||a.ar||'';
      html+='<span class="tj-ay">'+applyTajweedColors(tx)
        +'<span class="tj-num">'+a.numberInSurah+'</span></span> ';
    });
    box.innerHTML='<div class="tj-body" style="line-height:3.2;text-align:center;direction:rtl;font-size:1.25rem;">'+html+'</div>';
  }
  fetch('data/quran/quran-uthmani/'+sn+'.json').then(function(r){return r.ok?r.json():null;}).then(function(j){
    var ays=(j&&j.data&&j.data.ayahs)||(j&&j.ayahs)||null;
    if(ays&&ays.length){ paint(ays); return; }
    throw new Error('local miss');
  }).catch(function(){
    if(typeof HudaQuran==='undefined'){ box.innerHTML='<div style="color:#c44;text-align:center;padding:1rem;">تعذّر التحميل</div>'; return; }
    HudaQuran.fetch('https://api.alquran.cloud/v1/surah/'+sn+'/quran-uthmani')
      .then(function(r){return r.json();})
      .then(function(d){
        if(!d.data||!d.data.ayahs){box.innerHTML='<div style="color:#e87a7a;text-align:center;">⚠️ تعذّر التحميل</div>';return;}
        paint(d.data.ayahs);
      })
      .catch(function(){ box.innerHTML='<div style="color:#e87a7a;text-align:center;padding:2rem;">⚠️ تعذّر التحميل</div>'; });
  });
}


// hifz-page-observer
(function(){
  function tryBuild(){
    var p = document.getElementById('page-hifz');
    if (p && p.classList.contains('on') && typeof buildHifz === 'function') buildHifz();
  }
  document.addEventListener('DOMContentLoaded', function(){
    tryBuild();
    var obs = new MutationObserver(tryBuild);
    var p = document.getElementById('page-hifz');
    if (p) obs.observe(p, { attributes: true, attributeFilter: ['class'] });
  });
  var _sp = window.SP;
  if (typeof _sp === 'function') {
    window.SP = function(id, ph) {
      var r = _sp.apply(this, arguments);
      if (id === 'hifz') setTimeout(function(){ if (typeof buildHifz==='function') buildHifz(); }, 30);
      return r;
    };
  }
})();

// updateKhatmaBookmarkUI on load
document.addEventListener('DOMContentLoaded', function(){ setTimeout(function(){ try{ updateKhatmaBookmarkUI(); }catch(e){} }, 400); });
